  game.platinum = game.platinum.sub(g.rt.PU1AmountToBuy * 200);
  game.platinumUpgradesBought[0] += g.rt.PU1AmountToBuy;
  g.rt.PU2AmountCanBuy = game.platinum.div(500).floor();
  g.rt.PU2AmountToBuy = Decimal.min(g.rt.PU2AmountCanBuy, 20 - game.platinumUpgradesBought[1]).toNumber();
